"""Virtual address space auditing for the wvas diagnostic collector.

The collector asks three questions about a target process:

``regions(pid)``
    Which parts of the virtual address space does the process have in use?

``file_backed_regions(pid)``
    Which of those parts are backed by a file on disk, and which file?

``modules(pid)``
    Which executable images are loaded, and where?

The answers are what the field engineers read when a machine reports
"something keeps the log file mapped" or "the process has no address space
left", so they have to describe the target process, not a snapshot of an
earlier call.

Three promises this module keeps, because a report that breaks any of them is
worse than no report:

* addresses and lengths are reported at the full width of the machine. A
  64 bit process really does live above 4 GiB, and a reservation really can
  be wider than 4 GiB.
* a path in a report can be opened by whoever reads it. Win32 hands out NT
  device paths (``\\Device\\HarddiskVolume4\\...``) and named section names
  (``\\Sessions\\1\\BaseNamedObjects\\...``); neither can be pasted into a
  ticket, so they are translated into a drive letter or a UNC path, or dropped
  to ``None`` when no such translation exists.
* every failure is a :class:`~wvas.errors.WVasError` with a machine readable
  ``kind``; Win32 error codes never escape as bare ``OSError``.
"""

import ctypes
import ctypes.wintypes as wt
import functools
import re

from . import _winapi as w
from .errors import WVasError

#: size of the buffers used for names coming back from Win32
PATH_BUFFER_CHARS = 32768

_PROTECTION_NAMES = {
    w.PAGE_NOACCESS: "none",
    w.PAGE_READONLY: "r",
    w.PAGE_READWRITE: "rw",
    w.PAGE_WRITECOPY: "wc",
    w.PAGE_EXECUTE: "x",
    w.PAGE_EXECUTE_READ: "xr",
    w.PAGE_EXECUTE_READWRITE: "xrw",
    w.PAGE_EXECUTE_WRITECOPY: "xwc",
}

_TYPE_NAMES = {
    w.MEM_IMAGE: "image",
    w.MEM_MAPPED: "mapped",
    w.MEM_PRIVATE: "private",
}

_STATE_NAMES = {
    w.MEM_COMMIT: "commit",
    w.MEM_RESERVE: "reserve",
}

# The mask of a protection field: the base access right plus the modifiers
# (PAGE_GUARD, PAGE_NOCACHE, PAGE_WRITECOMBINE) that ride along with it.
_PROTECTION_MASK = 0xFF

# A device path is "\Device\Something\...": a root name followed by a path.
_DEVICE_PATH = re.compile(r"^(\\[?.\\]*[^\\]+)(\\+.*)$", re.DOTALL)

# Names the object manager hands out for things that are not files. They must
# not be mistaken for a path somebody could open.
_NON_FILE_PREFIXES = (
    "\\sections\\",
    "\\session\\",
    "\\sessions\\",
    "\\basenamedobjects\\",
    "\\known dlls\\",
    "\\windows\\",
    "\\memcompression",
)


def protection_name(protect):
    """Map a PAGE_* protection value onto its short textual name."""
    return _PROTECTION_NAMES.get(protect & _PROTECTION_MASK, "?")


def type_name(region_type):
    """Map a MEM_* region type onto its short textual name."""
    return _TYPE_NAMES.get(region_type, "private")


# ---------------------------------------------------------------------------
# naming files: from whatever Win32 hands out to something a caller can open
# ---------------------------------------------------------------------------

@functools.lru_cache(maxsize=None)
def _dos_devices():
    """Map every NT device name known to this session onto a DOS path.

    ``\\Device\\HarddiskVolume4`` -> ``C:``, ``\\Device\\Mup`` -> ``\\\\`` and
    so on. Built by enumerating the session's DOS devices and asking Win32 what
    each of them points at; a device can have several names (a drive letter and
    a volume GUID) so they are all recorded, preferring the ones a human would
    recognise.
    """
    query = w.function("QueryDosDeviceW")
    if query is None:
        return {}

    listing = _query_dos_devices(query, None)
    devices = {}
    for name in listing:
        if name.endswith("$") or "#" in name:
            continue  # CONIN$, LPT1 and friends are not files on a volume
        targets = _query_dos_devices(query, name)
        if not targets:
            continue
        target = targets[0]
        current = devices.get(target)
        if current is None or _device_name_rank(name) < _device_name_rank(current):
            devices[target] = name
    return devices


def _device_name_rank(name):
    """Prefer short, human readable device names (``C:`` over a volume GUID)."""
    plain = name.rstrip(":")
    if len(plain) == 1 and plain.isalpha():
        return 0
    if not plain.lower().startswith("volume"):
        return 1
    return 2


def _query_dos_devices(query, name):
    """One ``QueryDosDeviceW`` call, returning its multi-string as a list."""
    size = 1 << 12
    while size <= (1 << 18):
        buffer = ctypes.create_unicode_buffer(size)
        written = query(name, buffer, size)
        if written:
            return _multi_string(buffer, written)
        error = w.last_error()
        if error != w.ERROR_INSUFFICIENT_BUFFER:
            return []
        size *= 4
    return []


def _multi_string(buffer, chars):
    """Split a Win32 multi-string (double NUL terminated) into its parts."""
    text = ctypes.string_at(ctypes.cast(buffer, ctypes.c_void_p), chars * 2)
    text = text.decode("utf-16-le", "replace")
    return [part for part in text.split("\0") if part]


@functools.lru_cache(maxsize=None)
def _volume_names():
    """Fallback device table: volume GUID name -> first mounted DOS path.

    ``QueryDosDeviceW`` only sees the calling logon session, which can miss the
    volume a target process keeps a file on. ``\\\\?\\Volume{...}\\`` works
    from any session, so the mounted path names of a volume give the same
    answer through a different door.
    """
    resolve = w.function("GetVolumePathNamesForVolumeNameW")
    if resolve is None:
        return {}
    query = w.function("QueryDosDeviceW")
    if query is None:
        return {}

    names = {}
    listing = _query_dos_devices(query, None)
    for entry in listing:
        if not entry.lower().startswith("volume{"):
            continue
        target = "\\\\?\\" + entry + "\\"
        wanted = wt.DWORD()
        buffer = ctypes.create_unicode_buffer(1024)
        ok = resolve(target, buffer, len(buffer), ctypes.byref(wanted))
        if not ok:
            if w.last_error() == w.ERROR_INSUFFICIENT_BUFFER and wanted.value:
                buffer = ctypes.create_unicode_buffer(wanted.value + 8)
                ok = resolve(target, buffer, len(buffer), ctypes.byref(wanted))
            if not ok:
                continue
        path_names = _multi_string(buffer, wanted.value or len(buffer))
        if not path_names:
            continue
        device = "\\Device\\" + entry
        names[device] = path_names[0].rstrip("\\") + ":"
    return names


def _is_openable(path):
    """True when ``path`` is a drive letter or UNC path a caller can open."""
    if len(path) >= 3 and path[1] == ":" and path[2] in ("\\", "/"):
        return True
    if path.startswith("\\\\") and not path.startswith("\\\\?"):
        return True
    return False


def _device_dos_path(device):
    """The DOS path a device name is mounted at, or None."""
    devices = _dos_devices()
    name = devices.get(device)
    if name is None:
        name = _volume_names().get(device)
    if not name:
        return None
    return name.rstrip("\\")


def _dos_path(nt_path):
    """Translate an NT device path into a path the caller can open.

    Returns None when the name is not a file at all (a named section, a
    compressed memory store, a session object) or when no DOS name for it can
    be found; callers then report "no file behind this region" rather than a
    string that opens nothing.
    """
    if not nt_path:
        return None

    path = nt_path.replace("/", "\\")
    while path.startswith("\\??\\") or path.startswith("\\\\.\\"):
        path = path[4:]
    if not path:
        return None
    if _is_openable(path):
        # Already something a caller can open: keep it, but never in the
        # extended length spelling.
        return None if path.startswith("\\\\?") else path
    if path.lower().startswith(_NON_FILE_PREFIXES):
        return None

    match = _DEVICE_PATH.match(path)
    if not match:
        return None
    device = match.group(1).rstrip("\\")
    tail = match.group(2)
    dos_device = _device_dos_path(device)
    if dos_device is None:
        return None
    candidate = dos_device + tail
    while "\\\\" in candidate:
        candidate = candidate.replace("\\\\", "\\")
    # A share mapping resolves to the bare UNC root; keep the tail readable.
    return candidate.rstrip("\\") or None


# ---------------------------------------------------------------------------
# talking to Win32
# ---------------------------------------------------------------------------

def _fail(message, pid, error=None):
    """Build the WVasError that classifies Win32 failure ``error``."""
    kind = _error_kind(error)
    if error:
        message = "%s (Win32 error %d)" % (message, error)
    return WVasError(message, kind=kind, pid=pid)


def _error_kind(error):
    """Classify a Win32 error code into the wvas error taxonomy."""
    if not error:
        return "query-failed"
    if error in (w.ERROR_ACCESS_DENIED, w.ERROR_PRIVILEGE_NOT_HELD
                 if hasattr(w, "ERROR_PRIVILEGE_NOT_HELD") else 1314):
        return "access-denied"
    if error in (w.ERROR_CALL_NOT_IMPLEMENTED, w.ERROR_INVALID_FUNCTION):
        return "unsupported"
    return "query-failed"


def _check_platform(pid):
    if not w.available():
        raise WVasError(
            w.load_error() or "address space queries are not supported here",
            kind="unsupported",
            pid=pid,
        )


def _check_pid(pid):
    if isinstance(pid, bool) or not isinstance(pid, int):
        raise WVasError("pid must be a positive integer", kind="badarg", pid=pid)
    if pid <= 0 or pid > w.MAXIMUM_PID:
        raise WVasError("pid must be a positive integer", kind="badarg", pid=pid)


def _pid_exists(pid):
    """Best effort answer to "is there a process with this id?"."""
    enumerate_processes = w.function("EnumProcesses")
    if enumerate_processes is None:
        return True
    size = 4096
    while size <= (1 << 18):
        table = (wt.DWORD * size)()
        needed = wt.DWORD(0)
        if enumerate_processes(table, ctypes.sizeof(table), ctypes.byref(needed)):
            count = min(size, needed.value // ctypes.sizeof(wt.DWORD))
            return pid in table[:count]
        size *= 4
    return True


def _open_process(pid):
    """Open ``pid`` for querying, classifying every way that can fail."""
    _check_platform(pid)
    _check_pid(pid)

    wanted = w.PROCESS_QUERY_INFORMATION | w.PROCESS_VM_READ
    attempts = (
        wanted,
        w.PROCESS_QUERY_INFORMATION | w.PROCESS_VM_READ,
        w.PROCESS_QUERY_LIMITED_INFORMATION,
    )
    error = 0
    for access in attempts:
        handle = w.OpenProcess(access, False, pid)
        if handle:
            return handle
        error = w.last_error() or error
        if error == w.ERROR_ACCESS_DENIED:
            # Either the process has gone or we are not allowed to look at it;
            # say which one, because the two mean different things to support.
            if not _pid_exists(pid):
                raise WVasError(
                    "no such process", kind="no-such-process", pid=pid
                )
            raise WVasError("access denied", kind="access-denied", pid=pid)
    if not error:
        error = w.last_error()
    raise _fail("cannot open process", pid, error)


def _close_process(handle):
    try:
        if handle and w.CloseHandle:
            w.CloseHandle(handle)
    except (OSError, ValueError):  # pragma: no cover - closing cannot matter
        pass


# ---------------------------------------------------------------------------
# the address space itself
# ---------------------------------------------------------------------------

def _image_paths(handle, pid):
    """Map the base address of every loaded image onto its DOS path.

    Built from the module list of the process, which is the only place Win32
    gives the file name of an image with its load address attached. A module
    whose file name cannot be translated still appears, with ``None``.
    """
    paths = {}
    for base, size, path in _list_modules(handle, pid):
        if base is None:
            continue
        paths.setdefault(base, path)
    return paths


def _region_path(handle, mbi, image_paths):
    """The file behind this region, as a path the caller can open."""
    base = mbi.BaseAddress or 0
    if mbi.Type == w.MEM_IMAGE:
        path = image_paths.get(base)
        if path is None:
            path = image_paths.get(mbi.AllocationBase or 0)
        if path is None:
            path = _dos_path(_mapped_file_name(handle, base))
        return path
    if mbi.Type == w.MEM_MAPPED:
        return _dos_path(_mapped_file_name(handle, base))
    # Private memory is never file backed, and asking about it can raise on a
    # page that is no longer readable.
    return None


def _mapped_file_name(handle, address):
    """The NT name Win32 gives for the file mapped at ``address``."""
    query = w.function("GetMappedFileNameW")
    if query is None:
        return None
    buffer = ctypes.create_unicode_buffer(PATH_BUFFER_CHARS)
    written = query(handle, ctypes.c_void_p(address), buffer, len(buffer))
    if not written:
        # Anonymous sections, unnamed page file backed views and pages that
        # stopped being readable all come back empty: no file to report.
        return None
    return buffer.value or None


def _list_modules(handle, pid):
    """Yield ``(base, size, path)`` for each image loaded in the process.

    Each image is reported once, lowest base address first. An image whose
    file name cannot be turned into a path the caller can open is still
    reported, with ``None`` for the path.
    """
    enumerate_modules = w.function("EnumProcessModulesEx")
    if enumerate_modules is None:
        return []

    flag_sets = _module_flag_sets(handle)
    seen = {}
    error = 0
    for flags in flag_sets:
        for base in _enumerate_module_bases(handle, enumerate_modules, flags):
            if base in seen:
                continue
            seen[base] = _module_entry(handle, base, pid)
        if seen:
            break
        error = w.last_error() or error

    if not seen and error in (w.ERROR_ACCESS_DENIED, 5):
        raise _fail("cannot list the loaded images", pid, error)
    if not seen and error:
        # A 32 bit collector looking at a 64 bit process, or a process that is
        # gone: nothing to report rather than a failure of the query itself.
        return []

    entries = sorted(seen.values(), key=lambda item: item[0])
    return entries


def _module_flag_sets(handle):
    """Which ``LIST_MODULES_*`` filters to try, in order of preference."""
    sets = [w.LIST_MODULES_DEFAULT]
    if w.LIST_MODULES_ALL not in sets:
        sets.append(w.LIST_MODULES_ALL)
    if _is_wow64(handle) and w.LIST_MODULES_32BIT not in sets:
        sets.append(w.LIST_MODULES_32BIT)
    if w.LIST_MODULES_64BIT not in sets:
        sets.append(w.LIST_MODULES_64BIT)
    return sets


def _is_wow64(handle):
    try:
        is_wow64 = w.kernel32.IsWow64Process
        is_wow64.argtypes = [wt.HANDLE, ctypes.POINTER(wt.BOOL)]
        is_wow64.restype = wt.BOOL
        result = wt.BOOL(False)
        if is_wow64(handle, ctypes.byref(result)):
            return bool(result.value)
    except (AttributeError, OSError, ValueError):
        pass
    return False


def _enumerate_module_bases(handle, enumerate_modules, flags):
    """One ``EnumProcessModulesEx`` sweep, returning the image base addresses."""
    slots = 1024
    bases = []
    while slots <= (1 << 17):
        table = (wt.HMODULE * slots)()
        needed = wt.DWORD(0)
        ok = enumerate_modules(
            handle, table, ctypes.sizeof(table), ctypes.byref(needed), flags
        )
        if ok and not needed.value:
            return bases
        if not ok and w.last_error() != w.ERROR_BAD_LENGTH:
            return bases
        count = (needed.value or ctypes.sizeof(table)) // ctypes.sizeof(wt.HMODULE)
        if count <= slots:
            for index in range(min(count, slots)):
                base = table[index]
                if base:
                    bases.append(base)
            return bases
        slots = max(slots * 2, count + 16)
    return bases


def _module_entry(handle, base, pid):
    """``(base, size, path)`` for the image loaded at ``base``."""
    return (base, _module_size(handle, base), _module_path(handle, base, pid))


def _module_size(handle, base):
    """The size of the image loaded at ``base``, as Win32 reports it."""
    query = w.function("GetModuleInformation")
    if query is not None:
        info = w.MODULEINFO()
        if query(handle, wt.HMODULE(base), ctypes.byref(info), ctypes.sizeof(info)):
            if info.SizeOfImage:
                return int(info.SizeOfImage)
    # Fall back to walking the committed image regions of this load address.
    return _region_span(handle, base)


def _module_path(handle, base, pid):
    """The DOS path of the image loaded at ``base``, or None."""
    query = w.function("GetModuleFileNameExW")
    if query is not None:
        buffer = ctypes.create_unicode_buffer(PATH_BUFFER_CHARS)
        written = query(handle, wt.HMODULE(base), buffer, len(buffer))
        if written:
            path = _dos_path(buffer.value)
            if path:
                return path
    # The image name could not be turned into an openable path (a mapped
    # section without a file, a device that is not mounted here). Say so
    # instead of handing the caller a string that opens nothing.
    return _dos_path(_mapped_file_name(handle, base))


def _region_span(handle, base):
    """Total length of the committed regions belonging to the image at base."""
    info = w.MEMORY_BASIC_INFORMATION()
    total = 0
    address = base
    while True:
        written = w.VirtualQueryEx(
            handle, ctypes.c_void_p(address), ctypes.byref(info), ctypes.sizeof(info)
        )
        if not written:
            break
        region_base = info.BaseAddress or 0
        if region_base != base and (info.AllocationBase or 0) != base:
            break
        if info.State == w.MEM_COMMIT:
            total += int(info.RegionSize)
        address = region_base + int(info.RegionSize)
        if address <= region_base:
            break
    return total


def _walk_regions(handle):
    """Every region ``VirtualQueryEx`` reports, in ascending address order."""
    info = w.MEMORY_BASIC_INFORMATION()
    regions = []
    address = 0
    while True:
        written = w.VirtualQueryEx(
            handle, ctypes.c_void_p(address), ctypes.byref(info), ctypes.sizeof(info)
        )
        if not written:
            # End of the user address space, or a page that cannot be queried.
            break
        base = info.BaseAddress or 0
        size = int(info.RegionSize)
        if info.State != w.MEM_FREE:
            regions.append((
                int(base),
                size,
                _STATE_NAMES.get(info.State, "commit"),
                type_name(info.Type),
                protection_name(info.Protect),
                info.Type,
                base,
            ))
        address = base + size
        if size <= 0 or address <= base:
            break
    return regions


def regions(pid, include_reserved=True):
    """Return the regions of ``pid``'s virtual address space.

    Every region is a dict with the keys ``base``, ``size``, ``state``,
    ``type``, ``protect``, ``path`` and ``image``, sorted by ``base``.
    ``include_reserved`` decides whether reserved-but-uncommitted ranges take
    part; committed regions are always reported.
    """
    _check_platform(pid)
    _check_pid(pid)
    handle = _open_process(pid)
    try:
        walked = _walk_regions(handle)
        if not walked and w.last_error() not in (0, w.ERROR_INVALID_PARAMETER):
            raise _fail("cannot query the address space", pid, w.last_error())
        image_paths = _image_paths(handle, pid)
        result = []
        for base, size, state, kind, protect, type_value, raw_base in walked:
            if state == "reserve" and not include_reserved:
                continue
            path = None
            if state == "commit":
                path = _region_path_for(handle, raw_base, type_value, image_paths)
            result.append({
                "base": base,
                "size": size,
                "state": state,
                "type": kind,
                "protect": protect,
                "path": path,
                "image": kind == "image",
            })
        result.sort(key=lambda item: item["base"])
        return result
    finally:
        _close_process(handle)


def _region_path_for(handle, base, type_value, image_paths):
    """Path lookup for one walked region, keeping its raw base address."""

    class _Probe(object):
        """Just enough of MEMORY_BASIC_INFORMATION for the path helpers."""

        def __init__(self, base, type_value):
            self.BaseAddress = base
            self.Type = type_value
            self.AllocationBase = base

    return _region_path(handle, _Probe(base, type_value), image_paths)


def file_backed_regions(pid):
    """Return only the regions that have a file behind them."""
    return [item for item in regions(pid) if item["path"] is not None]


def modules(pid):
    """Return the loaded executable images, lowest base address first."""
    _check_platform(pid)
    _check_pid(pid)
    handle = _open_process(pid)
    try:
        return [
            {"path": path, "base": base, "size": size}
            for base, size, path in _list_modules(handle, pid)
        ]
    finally:
        _close_process(handle)

