PATH_BUFFER_CHARS = 32768

_PROTECTION_NAMES = {
    w.PAGE_NOACCESS: "none",
    w.PAGE_READONLY: "r",
    w.PAGE_READWRITE: "rw",
    w.PAGE_WRITECOPY: "wc",
    w.PAGE_EXECUTE: "x",
    w.PAGE_EXECUTE_READ: "xr",
    w.PAGE_EXECUTE_READWRITE: "xrw",
    w.PAGE_EXECUTE_WRITECOPY: "xwc",
}

_TYPE_NAMES = {
    w.MEM_IMAGE: "image",
    w.MEM_MAPPED: "mapped",
    w.MEM_PRIVATE: "private",
}

_STATE_NAMES = {
    w.MEM_COMMIT: "commit",
    w.MEM_RESERVE: "reserve",
}

#: the base access right of a protection field; PAGE_GUARD, PAGE_NOCACHE and
#: PAGE_WRITECOMBINE ride along with it and are not part of the short name.
_PROTECTION_MASK = 0xFF

#: "\Device\Something" followed by the path inside it
_DEVICE_PATH = re.compile(r"^(\\[?.\\]*[^\\]+)(\\+.*)$", re.DOTALL)

#: object manager names that are never a file somebody can open
_NON_FILE_PREFIXES = (
    "\\sections\\",
    "\\session\\",
    "\\sessions\\",
    "\\basenamedobjects\\",
    "\\known dlls\\",
    "\\windows\\",
    "\\memcompression",
)

#: one region as VirtualQueryEx reported it, at full address width
_Region = namedtuple(
    "_Region", "base size state type protect type_value allocation_base"
)


def protection_name(protect):
    """Map a PAGE_* protection value onto its short textual name."""
    return _PROTECTION_NAMES.get(protect & _PROTECTION_MASK, "?")


def type_name(region_type):
    """Map a MEM_* region type onto its short textual name."""
    return _TYPE_NAMES.get(region_type, "private")


# ---------------------------------------------------------------------------
# naming files: from whatever Win32 hands out to something a caller can open
# ---------------------------------------------------------------------------

def _multi_string(buffer, chars):
    """Split a Win32 multi-string (double NUL terminated) into its parts."""
    raw = ctypes.string_at(ctypes.cast(buffer, ctypes.c_void_p), chars * 2)
    text = raw.decode("utf-16-le", "replace")
    return [part for part in text.split("\0") if part]


def _query_dos_devices(query, name):
    """One ``QueryDosDeviceW`` call, returning its multi-string as a list."""
    size = 1 << 12
    while size <= (1 << 18):
        buffer = ctypes.create_unicode_buffer(size)
        written = query(name, buffer, size)
        if written:
            return _multi_string(buffer, written)
        if w.last_error() != w.ERROR_INSUFFICIENT_BUFFER:
            return []
        size *= 4
    return []


def _device_name_rank(name):
    """Prefer short, human readable device names (``C:`` over a volume GUID)."""
    plain = name.rstrip(":")
    if len(plain) == 1 and plain.isalpha():
        return 0
    if not plain.lower().startswith("volume{"):
        return 1
    return 2


@functools.lru_cache(maxsize=None)
def _dos_devices():
    """Map every NT device name known to this session onto a DOS path.

    ``\\Device\\HarddiskVolume4`` -> ``C:``, ``\\Device\\Mup`` -> ``\\\\`` and
    so on. Built by enumerating the session's DOS devices and asking Win32 what
    each one points at. A device can carry several names (a drive letter and a
    volume GUID), so the most readable of them wins.
    """
    query = w.function("QueryDosDeviceW")
    if query is None:
        return {}

    devices = {}
    for name in _query_dos_devices(query, None):
        if name.endswith("$") or "#" in name:
            continue  # CONIN$, LPT1 and friends do not name files on a volume
        targets = _query_dos_devices(query, name)
        if not targets:
            continue
        target = targets[0]
        current = devices.get(target)
        if current is None or _device_name_rank(name) < _device_name_rank(current):
            devices[target] = name
    return devices


@functools.lru_cache(maxsize=None)
def _volume_devices():
    """Fallback device table: NT volume name -> first mounted DOS path.

    ``QueryDosDeviceW`` only sees the DOS devices of the calling logon session,
    which can miss the volume a target process keeps a file on. The
    ``\\\\?\\Volume{...}\\`` spelling works from any session, so the mount
    points of a volume give the same answer through a different door.
    """
    query = w.function("QueryDosDeviceW")
    resolve = w.function("GetVolumePathNamesForVolumeNameW")
    if query is None or resolve is None:
        return {}

    names = {}
    for entry in _query_dos_devices(query, None):
        if not entry.lower().startswith("volume{"):
            continue
        wanted = wt.DWORD(0)
        buffer = ctypes.create_unicode_buffer(1024)
        volume = "\\\\?\\" + entry + "\\"
        if not resolve(volume, buffer, len(buffer), ctypes.byref(wanted)):
            if w.last_error() != w.ERROR_MORE_DATA or not wanted.value:
                continue
            buffer = ctypes.create_unicode_buffer(wanted.value + 8)
            if not resolve(volume, buffer, len(buffer), ctypes.byref(wanted)):
                continue
        mounted = _multi_string(buffer, wanted.value or len(buffer))
        if not mounted:
            continue
        names["\\Device\\" + entry] = mounted[0].rstrip("\\") + ":"
    return names


def _is_openable(path):
    """True when ``path`` is a drive letter or UNC path a caller can open."""
    if len(path) >= 3 and path[1] == ":" and path[2] in ("\\", "/"):
        return True
    return path.startswith("\\\\") and not path.startswith("\\\\?")


def _device_dos_path(device):
    """The DOS path a device name is mounted at, or None."""
    name = _dos_devices().get(device) or _volume_devices().get(device)
    if not name:
        return None
    return name.rstrip("\\")


def _dos_path(nt_path):
    """Translate an NT device path into a path the caller can open.

    Returns None when the name is not a file at all (a named section, a
    compressed memory store, a session object), and when no DOS name for the
    device can be found; callers then report "no file behind this region"
    rather than a string that opens nothing.
    """
    if not nt_path:
        return None

    path = nt_path.replace("/", "\\")
    while path.startswith("\\??\\") or path.startswith("\\\\.\\"):
        path = path[4:]
    if not path:
        return None
    if _is_openable(path):
        return path
    if path.startswith("\\\\?"):
        return None  # extended length spelling: nobody can paste that
    if path.lower().startswith(_NON_FILE_PREFIXES):
        return None

    match = _DEVICE_PATH.match(path)
    if not match:
        return None
    device = match.group(1).rstrip("\\")
    dos_device = _device_dos_path(device)
    if dos_device is None:
        return None
    candidate = dos_device + match.group(2)
    while "\\\\" in candidate:
        candidate = candidate.replace("\\\\", "\\")
    return candidate.rstrip("\\") or None


# ---------------------------------------------------------------------------
# talking to Win32
# ---------------------------------------------------------------------------

def _error_kind(error):
    """Classify a Win32 error code into the wvas error taxonomy."""
    if not error:
        return "query-failed"
    if error in (w.ERROR_ACCESS_DENIED, w.ERROR_PRIVILEGE_NOT_HELD,
                 w.ERROR_SHARING_VIOLATION):
        return "access-denied"
    if error in (w.ERROR_CALL_NOT_IMPLEMENTED, w.ERROR_INVALID_FUNCTION):
        return "unsupported"
    return "query-failed"


def _fail(message, pid, error=None):
    """The :class:`WVasError` that classifies Win32 failure ``error``."""
    if error:
        message = "%s (Win32 error %d)" % (message, error)
    return WVasError(message, kind=_error_kind(error), pid=pid)


def _check_platform(pid):
    if not w.available():
        raise WVasError(
            w.load_error() or "address space queries are not supported here",
            kind="unsupported",
            pid=pid,
        )


def _check_pid(pid):
    if isinstance(pid, bool) or not isinstance(pid, int):
        raise WVasError("pid must be a positive integer", kind="badarg", pid=pid)
    if pid <= 0 or pid > w.MAXIMUM_PID:
        raise WVasError("pid must be a positive integer", kind="badarg", pid=pid)


def _pid_exists(pid):
    """Best effort answer to "is there a process with this id?"."""
    enumerate_processes = w.function("EnumProcesses")
    if enumerate_processes is None:
        return True
    size = 4096
    while size <= (1 << 18):
        table = (wt.DWORD * size)()
        needed = wt.DWORD(0)
        if enumerate_processes(table, ctypes.sizeof(table), ctypes.byref(needed)):
            count = min(size, needed.value // ctypes.sizeof(wt.DWORD))
            return pid in table[:count]
        size *= 4
    return True


def _open_process(pid):
    """Open ``pid`` for querying, classifying every way that can fail."""
    _check_platform(pid)
    _check_pid(pid)

    error = 0
    for access in (
        w.PROCESS_QUERY_INFORMATION | w.PROCESS_VM_READ,
        w.PROCESS_QUERY_LIMITED_INFORMATION,
    ):
        handle = w.OpenProcess(access, False, pid)
        if handle:
            return handle
        error = w.last_error() or error
        if error == w.ERROR_ACCESS_DENIED:
            # Either the process has gone or we may not look at it; say which,
            # because the two mean different things to support.
            if not _pid_exists(pid):
                raise WVasError(
                    "no such process", kind="no-such-process", pid=pid
                )
            raise WVasError("access denied", kind="access-denied", pid=pid)
    if not error:
        error = w.last_error()
    raise _fail("cannot open process", pid, error)


def _close_process(handle):
    try:
        if handle and w.CloseHandle is not None:
            w.CloseHandle(handle)
    except (OSError, ValueError):  # pragma: no cover - a leaked handle is fine
        pass


# ---------------------------------------------------------------------------
# walking the address space
# ---------------------------------------------------------------------------

def _walk_regions(handle):
    """Every region ``VirtualQueryEx`` reports, ascending by base address."""
    info = w.MEMORY_BASIC_INFORMATION()
    size_of_info = ctypes.sizeof(info)
    walked = []
    address = 0
    while True:
        written = w.VirtualQueryEx(
            handle, ctypes.c_void_p(address), ctypes.byref(info), size_of_info
        )
        if not written:
            # Past the end of the user address space, or a page that cannot be
            # queried any more.
            break
        base = int(info.BaseAddress or 0)
        size = int(info.RegionSize)
        if info.State != w.MEM_FREE:
            walked.append(_Region(
                base,
                size,
                _STATE_NAMES.get(info.State, "commit"),
                type_name(info.Type),
                protection_name(info.Protect),
                int(info.Type),
                int(info.AllocationBase or base),
            ))
        address = base + size
        if size <= 0 or address <= base:
            break
    return walked


def _image_paths(handle, pid):
    """Map the load address of every image onto its path, None when unknown."""
    paths = {}
    for base, _size, path in _list_modules(handle, pid):
        paths.setdefault(base, path)
    return paths


def _mapped_file_name(handle, address):
    """The NT name Win32 gives for the file mapped at ``address``."""
    query = w.function("GetMappedFileNameW")
    if query is None:
        return None
    buffer = ctypes.create_unicode_buffer(PATH_BUFFER_CHARS)
    written = query(handle, ctypes.c_void_p(address), buffer, len(buffer))
    if not written:
        # Anonymous sections, unnamed page file backed views and pages that
        # stopped being readable all come back empty: no file to report.
        return None
    return buffer.value or None


def _region_path(handle, region, image_paths):
    """The file behind this region, as a path the caller can open."""
    if region.type_value == w.MEM_IMAGE:
        path = image_paths.get(region.base) or image_paths.get(region.allocation_base)
        if path is None:
            path = _dos_path(_mapped_file_name(handle, region.base))
        return path
    if region.type_value == w.MEM_MAPPED:
        return _dos_path(_mapped_file_name(handle, region.base))
    # Private memory is never file backed, and asking about it can fail on a
    # page that is no longer readable.
    return None


def regions(pid, include_reserved=True):
    """Return the regions of ``pid``'s virtual address space.

    Every region is a dict with the keys ``base``, ``size``, ``state``,
    ``type``, ``protect``, ``path`` and ``image``, ascending by ``base``.
    ``include_reserved`` decides whether reserved-but-uncommitted ranges take
    part; committed regions are always reported.
    """
    _check_platform(pid)
    _check_pid(pid)
    handle = _open_process(pid)
    try:
        walked = _walk_regions(handle)
        if not walked:
            error = w.last_error()
            if error not in (0, w.ERROR_INVALID_PARAMETER):
                raise _fail("cannot query the address space", pid, error)
        image_paths = _image_paths(handle, pid)
        result = []
        for region in walked:
            if region.state == "reserve" and not include_reserved:
                continue
            path = None
            if region.state == "commit":
                path = _region_path(handle, region, image_paths)
            result.append({
                "base": region.base,
                "size": region.size,
                "state": region.state,
                "type": region.type,
                "protect": region.protect,
                "path": path,
                "image": region.type == "image",
            })
        result.sort(key=lambda item: item["base"])
        return result
    finally:
        _close_process(handle)


def file_backed_regions(pid):
    """Return only the regions that have a file behind them."""
    return [item for item in regions(pid) if item["path"] is not None]


# ---------------------------------------------------------------------------
# the loaded images
# ---------------------------------------------------------------------------

def _is_wow64(handle):
    try:
        is_wow64 = w.kernel32.IsWow64Process
        is_wow64.argtypes = [wt.HANDLE, ctypes.POINTER(wt.BOOL)]
        is_wow64.restype = wt.BOOL
        result = wt.BOOL(False)
        if is_wow64(handle, ctypes.byref(result)):
            return bool(result.value)
    except (AttributeError, OSError, ValueError):
        pass
    return False


def _module_flag_sets(handle):
    """Which ``LIST_MODULES_*`` filters to try, in order of preference."""
    sets = [w.LIST_MODULES_DEFAULT]
    if _is_wow64(handle) and w.LIST_MODULES_32BIT not in sets:
        sets.append(w.LIST_MODULES_32BIT)
    for flags in (w.LIST_MODULES_ALL, w.LIST_MODULES_64BIT):
        if flags not in sets:
            sets.append(flags)
    return sets


def _enumerate_module_bases(handle, enumerate_modules, flags):
    """One ``EnumProcessModulesEx`` sweep: the load addresses it reports."""
    slots = 1024
    while slots <= (1 << 17):
        table = (wt.HMODULE * slots)()
        needed = wt.DWORD(0)
        ok = enumerate_modules(
            handle, table, ctypes.sizeof(table), ctypes.byref(needed), flags
        )
        if ok and not needed.value:
            return []
        if not ok and w.last_error() != w.ERROR_BAD_LENGTH:
            return []
        count = (needed.value or ctypes.sizeof(table)) // ctypes.sizeof(wt.HMODULE)
        if count <= slots:
            return [table[index] for index in range(min(count, slots)) if table[index]]
        slots = max(slots * 2, count + 16)
    return []


def _list_modules(handle, pid):
    """``(base, size, path)`` for each loaded image, once each, base ascending.

    An image whose file name cannot be turned into a path the caller can open
    is still reported, with ``None`` for the path.
    """
    enumerate_modules = w.function("EnumProcessModulesEx")
    if enumerate_modules is None:
        return []

    images = {}
    error = 0
    for flags in _module_flag_sets(handle):
        for base in _enumerate_module_bases(handle, enumerate_modules, flags):
            base = int(base)
            if base not in images:
                images[base] = (
                    base,
                    _module_size(handle, base),
                    _module_path(handle, base),
                )
        if images:
            break
        error = w.last_error() or error

    if not images and error == w.ERROR_ACCESS_DENIED:
        raise _fail("cannot list the loaded images", pid, error)
    # Nothing enumerable (a 32 bit collector facing a 64 bit process, a process
    # that is on its way out) is an empty answer, not a failed query.
    return sorted(images.values(), key=lambda item: item[0])


def _module_size(handle, base):
    """The size of the image loaded at ``base``, as Win32 reports it."""
    query = w.function("GetModuleInformation")
    if query is not None:
        info = w.MODULEINFO()
        if query(handle, wt.HMODULE(base), ctypes.byref(info), ctypes.sizeof(info)):
            if info.SizeOfImage:
                return int(info.SizeOfImage)
    return _image_span(handle, base)


def _image_span(handle, base):
    """Total length of the committed regions belonging to the image at base."""
    info = w.MEMORY_BASIC_INFORMATION()
    size_of_info = ctypes.sizeof(info)
    total = 0
    address = base
    while True:
        written = w.VirtualQueryEx(
            handle, ctypes.c_void_p(address), ctypes.byref(info), size_of_info
        )
        if not written:
            break
        region_base = int(info.BaseAddress or 0)
        if region_base != base and int(info.AllocationBase or 0) != base:
            break
        if info.State == w.MEM_COMMIT:
            total += int(info.RegionSize)
        address = region_base + int(info.RegionSize)
        if address <= region_base:
            break
    return total


def _module_path(handle, base):
    """The path of the image loaded at ``base``, or None when it has none."""
    query = w.function("GetModuleFileNameExW")
    if query is not None:
        buffer = ctypes.create_unicode_buffer(PATH_BUFFER_CHARS)
        written = query(handle, wt.HMODULE(base), buffer, len(buffer))
        if written:
            path = _dos_path(buffer.value)
            if path:
                return path
    # The name could not be turned into a path a caller can open (an image
    # mapped from a section without a file, a device not mounted here). Say so
    # instead of handing over a string that opens nothing.
    return _dos_path(_mapped_file_name(handle, base))


def modules(pid):
    """Return the loaded executable images, lowest base address first."""
    _check_platform(pid)
    _check_pid(pid)
    handle = _open_process(pid)
    try:
        return [
            {"path": path, "base": base, "size": size}
            for base, size, path in _list_modules(handle, pid)
        ]
    finally:
        _close_process(handle)

"""Virtual address space auditing for the wvas diagnostic collector.

The collector asks three questions about a target process:

``regions(pid)``
    Which parts of the virtual address space does the process have in use?

``file_backed_regions(pid)``
    Which of those parts are backed by a file on disk, and which file?

``modules(pid)``
    Which executable images are loaded, and where?

The answers are what the field engineers read when a machine reports
"something keeps the log file mapped" or "the process has no address space
left", so they have to describe the target process, not a snapshot of an
earlier call.

Three promises this module keeps, because a report that breaks any of them is
worse than no report:

* addresses and lengths are reported at the full width of the machine. A 64 bit
  process really does live above 4 GiB, and a reservation really can be wider
  than 4 GiB.
* a path in a report can be opened by whoever reads it. Win32 hands out NT
  device paths (``\\Device\\HarddiskVolume4\\...``) and section object names
  (``\\Sessions\\1\\BaseNamedObjects\\...``); neither can be pasted into a
  ticket, so both are translated into a drive letter or a UNC path, or dropped
  to ``None`` when no such translation exists.
* every failure is a :class:`~wvas.errors.WVasError` with a machine readable
  ``kind``; Win32 error codes never escape to the caller as a bare ``OSError``.
"""

import ctypes
import ctypes.wintypes as wt
import functools
import re
from collections import namedtuple

from . import _winapi as w
from .errors import WVasError

#: size of the buffers used for names coming back from Win32
PATH_BUFFER_CHARS = 32768

_PROTECTION_NAMES = {
    w.PAGE_NOACCESS: "none",
    w.PAGE_READONLY: "r",
    w.PAGE_READWRITE: "rw",
    w.PAGE_WRITECOPY: "wc",
    w.PAGE_EXECUTE: "x",
    w.PAGE_EXECUTE_READ: "xr",
    w.PAGE_EXECUTE_READWRITE: "xrw",
    w.PAGE_EXECUTE_WRITECOPY: "xwc",
}

_TYPE_NAMES = {
    w.MEM_IMAGE: "image",
    w.MEM_MAPPED: "mapped",
    w.MEM_PRIVATE: "private",
}

_STATE_NAMES = {
    w.MEM_COMMIT: "commit",
    w.MEM_RESERVE: "reserve",
}

#: the base access right of a protection field; PAGE_GUARD, PAGE_NOCACHE and
#: PAGE_WRITECOMBINE ride along with it and are not part of the short name.
_PROTECTION_MASK = 0xFF

#: device names that stand for "the share is named by the path itself"
_REDIRECTOR_DEVICES = re.compile(
    r"^\\device\\(mup|lanmanredirector|webdavredirector|davwwwclient|"
    r"hgfs|vmware\\hgfs|rdbss)$",
    re.IGNORECASE,
)

#: DOS device names that name a share namespace rather than a drive
_REDIRECTOR_NAMES = ("unc",)

#: sentinel for "this DOS device name cannot be used to build an open path"
_SKIP = object()

#: one region as VirtualQueryEx reported it, at full address width
_Region = namedtuple(
    "_Region", "base size state type protect type_value allocation_base"
)


def protection_name(protect):
    """Map a PAGE_* protection value onto its short textual name."""
    return _PROTECTION_NAMES.get(protect & _PROTECTION_MASK, "?")


def type_name(region_type):
    """Map a MEM_* region type onto its short textual name."""
    return _TYPE_NAMES.get(region_type, "private")


# ---------------------------------------------------------------------------
# naming files: from whatever Win32 hands out to something a caller can open
# ---------------------------------------------------------------------------

def _multi_string(buffer, chars):
    """Split a Win32 multi-string (double NUL terminated) into its parts."""
    raw = ctypes.string_at(ctypes.cast(buffer, ctypes.c_void_p), chars * 2)
    text = raw.decode("utf-16-le", "replace")
    return [part for part in text.split("\0") if part]


def _query_dos_devices(query, name):
    """One ``QueryDosDeviceW`` call, returning its multi-string as a list."""
    size = 1 << 12
    while size <= (1 << 18):
        buffer = ctypes.create_unicode_buffer(size)
        written = query(name, buffer, size)
        if written:
            return _multi_string(buffer, written)
        if w.last_error() != w.ERROR_INSUFFICIENT_BUFFER:
            return []
        size *= 4
    return []


def _device_name_rank(name):
    """Prefer short, human readable device names (``C:`` over a volume GUID)."""
    plain = name.rstrip(":")
    if len(plain) == 1 and plain.isalpha():
        return 0
    if not plain.lower().startswith("volume{"):
        return 1
    return 2


@functools.lru_cache(maxsize=None)
def _dos_devices():
    """The DOS devices of this logon session: NT device name -> DOS name.

    Built by enumerating the session's DOS devices and asking Win32 what each
    one points at, giving ``\\Device\\HarddiskVolume4`` -> ``C:``,
    ``\\Device\\Mup`` -> ``UNC`` and so on. A device can carry several names (a
    drive letter and a volume GUID); the most readable one wins.
    """
    query = w.function("QueryDosDeviceW")
    if query is None:
        return {}

    devices = {}
    for name in _query_dos_devices(query, None):
        if name.endswith("$") or "#" in name:
            continue  # CONIN$, LPT1 and friends do not name files on a volume
        targets = _query_dos_devices(query, name)
        if not targets:
            continue
        target = targets[0]
        current = devices.get(target)
        if current is None or _device_name_rank(name) < _device_name_rank(current):
            devices[target] = name
    return devices


@functools.lru_cache(maxsize=None)
def _volume_devices():
    """Fallback device table: NT volume name -> first mounted DOS path.

    ``QueryDosDeviceW`` only sees the DOS devices of the calling logon session,
    which can miss the volume a target process keeps a file on. The
    ``\\\\?\\Volume{...}\\`` spelling works from any session, so the mount
    points of a volume give the same answer through a different door.
    """
    query = w.function("QueryDosDeviceW")
    resolve = w.function("GetVolumePathNamesForVolumeNameW")
    if query is None or resolve is None:
        return {}

    names = {}
    for entry in _query_dos_devices(query, None):
        if not entry.lower().startswith("volume{"):
            continue
        wanted = wt.DWORD(0)
        buffer = ctypes.create_unicode_buffer(1024)
        volume = "\\\\?\\" + entry + "\\"
        if not resolve(volume, buffer, len(buffer), ctypes.byref(wanted)):
            if w.last_error() != w.ERROR_MORE_DATA or not wanted.value:
                continue
            buffer = ctypes.create_unicode_buffer(wanted.value + 8)
            if not resolve(volume, buffer, len(buffer), ctypes.byref(wanted)):
                continue
        mounted = _multi_string(buffer, wanted.value or len(buffer))
        if not mounted:
            continue
        names["\\Device\\" + entry] = mounted[0].rstrip("\\") + ":"
    return names


def _openable_root(device, name):
    """The DOS root ``name`` gives for ``device``, or a sentinel to skip it.

    ``None`` means "this device introduces a UNC path": the share name is part
    of the path itself, so the tail of the device path has to be prefixed with
    ``\\\\`` rather than with a drive letter.
    """
    if not name or "#" in name or "?" in name:
        return _SKIP
    if name.lower() in _REDIRECTOR_NAMES or _REDIRECTOR_DEVICES.match(device):
        return None
    if len(name) == 2 and name[1] == ":" and name[0].isalpha():
        return name
    if _is_openable(name):
        return name.rstrip("\\")
    return _SKIP


def _root_rank(root):
    """Prefer a drive letter over a UNC root when a device has both."""
    return 1 if root is None or root.startswith("\\\\") else 0


@functools.lru_cache(maxsize=None)
def _device_roots():
    """NT device name (lower cased) -> the DOS root that opens it."""
    roots = {}
    for device, name in _dos_devices().items():
        root = _openable_root(device, name)
        if root is _SKIP:
            continue
        key = device.lower()
        current = roots.get(key, _SKIP)
        if current is _SKIP or _root_rank(root) < _root_rank(current):
            roots[key] = root
    for device, root in _volume_devices().items():
        roots.setdefault(device.lower(), root.rstrip("\\"))
    return roots


def _is_openable(path):
    """True when ``path`` is a drive letter or UNC path a caller can open."""
    if len(path) >= 3 and path[1] == ":" and path[2] in ("\\", "/"):
        return True
    return path.startswith("\\\\") and not path.startswith("\\\\?")


def _join_device_root(root, tail):
    """Combine a DOS root with the path below it."""
    tail = tail.strip("\\")
    if root is None:
        # a share redirector: the tail already names the server and the share
        return "\\\\" + tail if tail else None
    if root.startswith("\\\\"):
        head, root = "\\\\", root[2:]
    else:
        head = ""
    joined = head + root + ("\\" + tail if tail else "")
    return joined or None


def _dos_path(nt_path):
    """Translate an NT device path into a path the caller can open.

    Returns None when the name is not a file somebody could open (a named
    section, a compressed memory store, a session object), and when no DOS
    device is known for the device the path lives on; callers then report "no
    file behind this region" rather than a string that opens nothing.
    """
    if not nt_path:
        return None

    path = nt_path.replace("/", "\\")
    while path.startswith("\\??\\") or path.startswith("\\\\.\\"):
        path = path[4:]
    if not path.startswith("\\"):
        return None
    if _is_openable(path):
        return path
    if path.startswith("\\\\?"):
        return None  # the extended length spelling opens nothing for a human

    roots = _device_roots()
    if not roots:
        return None

    # The device a path lives on can be one component deep (\Device\Mup) or
    # several (\Device\LanmanRedirector\server\share), so match the longest
    # device name that is a prefix of the path.
    match = None
    prefix = ""
    for part in path.split("\\"):
        if not part:
            continue
        prefix += "\\" + part
        root = roots.get(prefix.lower())
        if root is not _SKIP and prefix.lower() in roots:
            match = (prefix, roots[prefix.lower()])
    if match is None:
        return None
    device, root = match
    return _join_device_root(root, path[len(device):])


# ---------------------------------------------------------------------------
# talking to Win32
# ---------------------------------------------------------------------------

def _error_kind(error):
    """Classify a Win32 error code into the wvas error taxonomy."""
    if not error:
        return "query-failed"
    if error in (w.ERROR_ACCESS_DENIED, w.ERROR_SHARING_VIOLATION,
                 w.ERROR_PRIVILEGE_NOT_HELD):
        return "access-denied"
    if error in (w.ERROR_CALL_NOT_IMPLEMENTED, w.ERROR_INVALID_FUNCTION):
        return "unsupported"
    return "query-failed"


def _fail(message, pid, error=None):
    """The :class:`WVasError` that classifies Win32 failure ``error``."""
    if error:
        message = "%s (Win32 error %d)" % (message, error)
    return WVasError(message, kind=_error_kind(error), pid=pid)


def _check_platform(pid):
    if not w.available():
        raise WVasError(
            w.load_error() or "address space queries are not supported here",
            kind="unsupported",
            pid=pid,
        )


def _check_pid(pid):
    if isinstance(pid, bool) or not isinstance(pid, int):
        raise WVasError("pid must be a positive integer", kind="badarg", pid=pid)
    if pid <= 0 or pid > w.MAXIMUM_PID:
        raise WVasError("pid must be a positive integer", kind="badarg", pid=pid)


def _pid_exists(pid):
    """Best effort answer to "is there a process with this id?"."""
    enumerate_processes = w.function("EnumProcesses")
    if enumerate_processes is None:
        return True
    size = 4096
    while size <= (1 << 18):
        table = (wt.DWORD * size)()
        needed = wt.DWORD(0)
        if enumerate_processes(table, ctypes.sizeof(table), ctypes.byref(needed)):
            count = min(size, needed.value // ctypes.sizeof(wt.DWORD))
            return pid in table[:count]
        size *= 4
    return True


def _open_process(pid):
    """Open ``pid`` for querying, classifying every way that can fail."""
    _check_platform(pid)
    _check_pid(pid)

    error = 0
    for access in (
        w.PROCESS_QUERY_INFORMATION | w.PROCESS_VM_READ,
        w.PROCESS_QUERY_LIMITED_INFORMATION,
    ):
        handle = w.OpenProcess(access, False, pid)
        if handle:
            return handle
        error = w.last_error() or error
        if error == w.ERROR_ACCESS_DENIED:
            # Either the process has gone or we may not look at it; say which,
            # because the two mean different things to support.
            if not _pid_exists(pid):
                raise WVasError("no such process", kind="no-such-process", pid=pid)
            raise WVasError("access denied", kind="access-denied", pid=pid)
    if not error:
        error = w.last_error()
    raise _fail("cannot open process", pid, error)


def _close_process(handle):
    try:
        if handle and w.CloseHandle is not None:
            w.CloseHandle(handle)
    except (OSError, ValueError):  # pragma: no cover - a leaked handle is fine
        pass


# ---------------------------------------------------------------------------
# walking the address space
# ---------------------------------------------------------------------------

def _walk_regions(handle):
    """Every region ``VirtualQueryEx`` reports, ascending by base address."""
    info = w.MEMORY_BASIC_INFORMATION()
    size_of_info = ctypes.sizeof(info)
    walked = []
    address = 0
    while True:
        written = w.VirtualQueryEx(
            handle, ctypes.c_void_p(address), ctypes.byref(info), size_of_info
        )
        if not written:
            # Past the end of the user address space, or a page that cannot be
            # queried any more.
            break
        base = int(info.BaseAddress or 0)
        size = int(info.RegionSize)
        if info.State != w.MEM_FREE:
            walked.append(_Region(
                base,
                size,
                _STATE_NAMES.get(info.State, "commit"),
                type_name(info.Type),
                protection_name(info.Protect),
                int(info.Type),
                int(info.AllocationBase or base),
            ))
        address = base + size
        if size <= 0 or address <= base:
            break
    return walked


def _mapped_file_name(handle, address):
    """The NT name Win32 gives for the file mapped at ``address``."""
    query = w.function("GetMappedFileNameW")
    if query is None:
        return None
    buffer = ctypes.create_unicode_buffer(PATH_BUFFER_CHARS)
    written = query(handle, ctypes.c_void_p(address), buffer, len(buffer))
    if not written:
        # Anonymous sections, unnamed page file backed views and pages that
        # stopped being readable all come back empty: no file to report.
        return None
    return buffer.value or None


def _image_paths(handle):
    """Map the load address of every image onto its path, None when unknown."""
    paths = {}
    for base, _size, path in _list_modules(handle):
        paths.setdefault(base, path)
    return paths


def _region_path(handle, region, image_paths):
    """The file behind this region, as a path the caller can open."""
    if region.type_value == w.MEM_IMAGE:
        path = image_paths.get(region.base)
        if path is None:
            path = image_paths.get(region.allocation_base)
        if path is None:
            path = _dos_path(_mapped_file_name(handle, region.base))
        return path
    if region.type_value == w.MEM_MAPPED:
        return _dos_path(_mapped_file_name(handle, region.base))
    # Private memory is never file backed, and asking about it can fail on a
    # page that is no longer readable.
    return None


def regions(pid, include_reserved=True):
    """Return the regions of ``pid``'s virtual address space.

    Every region is a dict with the keys ``base``, ``size``, ``state``,
    ``type``, ``protect``, ``path`` and ``image``, ascending by ``base``.
    ``include_reserved`` decides whether reserved-but-uncommitted ranges take
    part; committed regions are always reported.
    """
    _check_platform(pid)
    _check_pid(pid)
    handle = _open_process(pid)
    try:
        walked = _walk_regions(handle)
        if not walked:
            error = w.last_error()
            if error not in (0, w.ERROR_INVALID_PARAMETER):
                raise _fail("cannot query the address space", pid, error)
        image_paths = _image_paths(handle)
        result = []
        for region in walked:
            if region.state == "reserve" and not include_reserved:
                continue
            path = None
            if region.state == "commit":
                path = _region_path(handle, region, image_paths)
            result.append({
                "base": region.base,
                "size": region.size,
                "state": region.state,
                "type": region.type,
                "protect": region.protect,
                "path": path,
                "image": region.type == "image",
            })
        result.sort(key=lambda item: item["base"])
        return result
    finally:
        _close_process(handle)


def file_backed_regions(pid):
    """Return only the regions that have a file behind them."""
    return [item for item in regions(pid) if item["path"] is not None]


# ---------------------------------------------------------------------------
# the loaded images
# ---------------------------------------------------------------------------

def _is_wow64(handle):
    try:
        is_wow64 = w.kernel32.IsWow64Process
        is_wow64.argtypes = [wt.HANDLE, ctypes.POINTER(wt.BOOL)]
        is_wow64.restype = wt.BOOL
        result = wt.BOOL(False)
        if is_wow64(handle, ctypes.byref(result)):
            return bool(result.value)
    except (AttributeError, OSError, ValueError):
        pass
    return False


def _module_flag_sets(handle):
    """Which ``LIST_MODULES_*`` filters to try, in order of preference."""
    sets = [w.LIST_MODULES_DEFAULT]
    if _is_wow64(handle) and w.LIST_MODULES_32BIT not in sets:
        sets.append(w.LIST_MODULES_32BIT)
    for flags in (w.LIST_MODULES_ALL, w.LIST_MODULES_64BIT):
        if flags not in sets:
            sets.append(flags)
    return sets


def _enumerate_module_bases(handle, enumerate_modules, flags):
    """One ``EnumProcessModulesEx`` sweep: the load addresses it reports."""
    slots = 1024
    while slots <= (1 << 17):
        table = (wt.HMODULE * slots)()
        needed = wt.DWORD(0)
        ok = enumerate_modules(
            handle, table, ctypes.sizeof(table), ctypes.byref(needed), flags
        )
        if ok and not needed.value:
            return []
        if not ok and w.last_error() != w.ERROR_BAD_LENGTH:
            return []
        count = (needed.value or ctypes.sizeof(table)) // ctypes.sizeof(wt.HMODULE)
        if count <= slots:
            return [table[index] for index in range(min(count, slots)) if table[index]]
        slots = max(slots * 2, count + 16)
    return []


def _list_modules(handle):
    """``(base, size, path)`` for each loaded image, once each, base ascending.

    An image whose file name cannot be turned into a path the caller can open
    is still reported, with ``None`` for the path.
    """
    enumerate_modules = w.function("EnumProcessModulesEx")
    if enumerate_modules is None:
        return []

    images = {}
    for flags in _module_flag_sets(handle):
        for base in _enumerate_module_bases(handle, enumerate_modules, flags):
            base = int(base)
            if base not in images:
                images[base] = (base, _module_size(handle, base), _module_path(handle, base))
        if images:
            break
    # Nothing enumerable (a 32 bit collector facing a 64 bit process, a process
    # that is on its way out) is an empty answer, not a failed query.
    return sorted(images.values(), key=lambda item: item[0])


def _module_size(handle, base):
    """The size of the image loaded at ``base``, as Win32 reports it."""
    query = w.function("GetModuleInformation")
    if query is not None:
        info = w.MODULEINFO()
        if query(handle, wt.HMODULE(base), ctypes.byref(info), ctypes.sizeof(info)):
            if info.SizeOfImage:
                return int(info.SizeOfImage)
    return _image_span(handle, base)


def _image_span(handle, base):
    """Total length of the committed regions belonging to the image at base."""
    info = w.MEMORY_BASIC_INFORMATION()
    size_of_info = ctypes.sizeof(info)
    total = 0
    address = base
    while True:
        written = w.VirtualQueryEx(
            handle, ctypes.c_void_p(address), ctypes.byref(info), size_of_info
        )
        if not written:
            break
        region_base = int(info.BaseAddress or 0)
        if region_base != base and int(info.AllocationBase or 0) != base:
            break
        if info.State == w.MEM_COMMIT:
            total += int(info.RegionSize)
        address = region_base + int(info.RegionSize)
        if address <= region_base:
            break
    return total


def _module_path(handle, base):
    """The path of the image loaded at ``base``, or None when it has none."""
    query = w.function("GetModuleFileNameExW")
    if query is not None:
        buffer = ctypes.create_unicode_buffer(PATH_BUFFER_CHARS)
        written = query(handle, wt.HMODULE(base), buffer, len(buffer))
        if written:
            path = _dos_path(buffer.value)
            if path:
                return path
    # The name could not be turned into a path a caller can open (an image
    # mapped from a section without a file, a device not mounted here). Say so
    # instead of handing over a string that opens nothing.
    return _dos_path(_mapped_file_name(handle, base))


def modules(pid):
    """Return the loaded executable images, lowest base address first."""
    _check_platform(pid)
    _check_pid(pid)
    handle = _open_process(pid)
    try:
        return [
            {"path": path, "base": base, "size": size}
            for base, size, path in _list_modules(handle)
        ]
    finally:
        _close_process(handle)
